import { newSpecPage } from '@stencil/core/testing';
import { ScPriceInput } from '../sc-price-input';
import { PRICE_INPUT_PATTERN } from '../../../../functions/currency';

describe('sc-price-input', () => {
  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScPriceInput],
      html: `<sc-price-input></sc-price-input>`,
    });
    expect(page.root).toMatchSnapshot();
  });

  it('uses the shared price pattern so validation matches the parser', async () => {
    // The pattern/parser agreement itself is contract-tested in currency.spec.ts.
    const page = await newSpecPage({
      components: [ScPriceInput],
      html: `<sc-price-input currency-code="eur"></sc-price-input>`,
    });
    expect(page.root.shadowRoot.querySelector('sc-input').getAttribute('pattern')).toBe(PRICE_INPUT_PATTERN);
  });
});
